import{_ as r,l as n,o as e,c as l,v as t,p as s,x as o,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"光子学图形化","description":"","frontmatter":{"title":"光子学图形化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/photonics-patterning.md","filePath":"litho/photonics-patterning.md","lastUpdated":1789023840000}'),E={name:"litho/photonics-patterning.md"};function c(m,a,_,u,B,D){const i=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="光子学图形化" tabindex="-1">光子学图形化 <a class="header-anchor" href="#光子学图形化" aria-label="Permalink to &quot;光子学图形化&quot;">​</a></h1><div class="epigraph"><p>波导损耗吃的是侧壁粗糙与宽度误差；NILS 与 LER 频谱在这里是光学损耗预算，不是 SRAM Vmin。</p><footer>—— 对照硅光波导对线宽与粗糙度敏感的公开讨论</footer></div><p><a href="/litho/hybrid-bonding-alignment">上一课</a>把 3D 电学对准收束。缺口是同一套硅工艺上的光子器件。本课钉光子学图形化。MEMS 厚胶与另一套规则，留给[下一课](/litho/mems-patterning）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>硅光波导：宽度误差改有效折射率与相位；LER/侧壁粗糙散射损耗。单模条件把宽度钉在百纳米量级，可用浸没甚至较成熟节点，但<strong>均匀性与粗糙</strong>规格可能严过同节点的数字逻辑。电子束直写在研制上常见（面积小）。与逻辑共集成时，BEOL 金属与光子层的热与 CMP 互相污染窗口。</p><p>缺口是<strong>损耗预算当光刻规格源</strong>，不是密度。把光子当「松一点的金属层」，相位器件会失败。</p><h3 id="不要重推成像" tabindex="-1">不要重推成像 <a class="header-anchor" href="#不要重推成像" aria-label="Permalink to &quot;不要重推成像&quot;">​</a></h3><p>光子器件仍用投影或 e-beam，成像物理已在主干。本课只改目标函数：损耗、相位匹配、耦合器 CD。</p><p><span class="marginnote">光栅耦合器对周期误差敏感，有点像干涉光刻的周期，但通常仍用掩模投影一次印出。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>规格：CDU、LER 频谱（散射相关长度）、侧壁角。工艺：可能专用刻蚀减粗糙（LER 传递课的滤波器）。计量：光学损耗本身是最终量，SEM 是代理。与 DTCO：波导不能随便填 dummy 金属在旁边——光学串扰。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>瑞利散射型侧壁损耗随粗糙功率谱与折射率对比变。低频宽度误差进相位。这与电学 LER 进 Vth 同构：频谱加权不同。平滑刻蚀在光子上是一等杠杆。</p>',13)),(e(),s(p,null,{default:o(()=>[h(i,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20CD%5B%22%E5%AE%BD%E5%BA%A6%20CDU%22%5D%20--%3E%20N%5B%22%E6%9C%89%E6%95%88%E6%8A%98%E5%B0%84%E7%8E%87%20%2F%20%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20LER%5B%22%E4%BE%A7%E5%A3%81%20PSD%22%5D%20--%3E%20LOSS%5B%22%E6%95%A3%E5%B0%84%E6%8D%9F%E8%80%97%22%5D%0A%20%20ETCH%5B%22%E8%BD%AC%E5%8D%B0%E5%B9%B3%E6%BB%91%22%5D%20--%3E%20LER%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把所有硅光当同一节点。不写 dB/cm 的万能数。本课不讲激光器外延。</p><p>后课默认：光子规格源是损耗；下一课 MEMS 规格源是力学与深宽比。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>光子图形化用 CDU 与 LER 频谱服务损耗与相位，不是晶体管密度。</li><li>同节点逻辑合格不代表波导合格。</li><li>刻蚀平滑在光子上是一等旋钮。</li><li>出处：硅光波导损耗与线宽/粗糙公开讨论。</li></ul>',5))])}const b=r(E,[["render",c]]);export{A as __pageData,b as default};
